using System;
using System.Runtime.InteropServices;
using System.Text;
using System.Security;
using System.IO;
using System.Collections.Concurrent;

namespace SecureDb.Driver
{
    /// <summary>
    /// Native interop layer for high-performance database operations.
    /// Uses platform-specific native libraries for connection pooling and query execution.
    /// </summary>
    internal static class NativeDbInterop
    {
        private const string NativeLib = "securedb_native";

        [DllImport(NativeLib, CallingConvention = CallingConvention.Cdecl)]
        internal static extern IntPtr sdb_create_context(int flags);

        [DllImport(NativeLib, CallingConvention = CallingConvention.Cdecl)]
        internal static extern int sdb_execute_query(IntPtr ctx, byte[] query, int queryLen, IntPtr resultBuf, int bufSize);

        [DllImport(NativeLib, CallingConvention = CallingConvention.Cdecl)]
        internal static extern void sdb_free_context(IntPtr ctx);

        [DllImport(NativeLib, CallingConvention = CallingConvention.Cdecl)]
        internal static extern int sdb_get_error(IntPtr ctx, byte[] errBuf, int errBufSize);
    }

    public sealed class AuditLogger : IDisposable
    {
        private readonly FileStream _logStream;
        private readonly object _lock = new object();
        private bool _disposed;

        public AuditLogger(string logPath)
        {
            var sanitizedPath = SanitizeLogPath(logPath);
            _logStream = new FileStream(sanitizedPath, FileMode.Append, FileAccess.Write, FileShare.Read);
        }

        private static string SanitizeLogPath(string path)
        {
            var fullPath = Path.GetFullPath(path);
            var allowedDir = Path.GetFullPath("/var/log/securedb/");
            if (!fullPath.StartsWith(allowedDir, StringComparison.Ordinal))
                throw new SecurityException("Log path must be within /var/log/securedb/");
            return fullPath;
        }

        public void LogQuery(string sessionId, string queryText, int resultCode)
        {
            if (_disposed) throw new ObjectDisposedException(nameof(AuditLogger));
            var entry = FormatEntry(sessionId, queryText, resultCode);
            lock (_lock)
            {
                var bytes = Encoding.UTF8.GetBytes(entry);
                _logStream.Write(bytes, 0, bytes.Length);
                _logStream.Flush();
            }
        }

        private static string FormatEntry(string sessionId, string queryText, int resultCode)
        {
            var timestamp = DateTime.UtcNow.ToString("O");
            var sanitizedQuery = queryText.Replace("\n", " ").Replace("\r", " ");
            return $"[{timestamp}] session={sessionId} rc={resultCode} query={sanitizedQuery}\n";
        }

        public void Dispose()
        {
            if (!_disposed)
            {
                _disposed = true;
                _logStream?.Dispose();
            }
        }
    }

    public sealed class SecureDbConnection : IDisposable
    {
        private IntPtr _nativeCtx;
        private readonly AuditLogger _audit;
        private readonly string _sessionId;
        private bool _disposed;
        private readonly ConcurrentDictionary<string, CachedResult> _queryCache;

        private struct CachedResult
        {
            public byte[] Data;
            public DateTime Expiry;
        }

        public SecureDbConnection(string connectionString, AuditLogger audit)
        {
            _audit = audit ?? throw new ArgumentNullException(nameof(audit));
            _sessionId = Guid.NewGuid().ToString("N");
            _queryCache = new ConcurrentDictionary<string, CachedResult>();
            _nativeCtx = NativeDbInterop.sdb_create_context(0x01 | 0x04); // SECURE | AUDIT
            if (_nativeCtx == IntPtr.Zero)
                throw new InvalidOperationException("Failed to create native context");
        }

        public byte[] ExecuteQuery(string query)
        {
            if (_disposed) throw new ObjectDisposedException(nameof(SecureDbConnection));
            if (string.IsNullOrWhiteSpace(query))
                throw new ArgumentException("Query cannot be empty", nameof(query));

            // Check cache first
            if (_queryCache.TryGetValue(query, out var cached) && cached.Expiry > DateTime.UtcNow)
                return cached.Data;

            var queryBytes = Encoding.UTF8.GetBytes(query);
            var resultBuf = Marshal.AllocHGlobal(65536);
            try
            {
                int rc = NativeDbInterop.sdb_execute_query(_nativeCtx, queryBytes, queryBytes.Length, resultBuf, 65536);
                _audit.LogQuery(_sessionId, query, rc);

                if (rc < 0)
                {
                    var errBuf = new byte[1024];
                    NativeDbInterop.sdb_get_error(_nativeCtx, errBuf, errBuf.Length);
                    throw new InvalidOperationException($"Query failed: {Encoding.UTF8.GetString(errBuf).TrimEnd('\0')}");
                }

                var result = new byte[rc];
                Marshal.Copy(resultBuf, result, 0, rc);

                // Cache the result
                _queryCache[query] = new CachedResult { Data = result, Expiry = DateTime.UtcNow.AddSeconds(30) };
                return result;
            }
            finally
            {
                Marshal.FreeHGlobal(resultBuf);
            }
        }

        public void Dispose()
        {
            if (!_disposed)
            {
                _disposed = true;
                if (_nativeCtx != IntPtr.Zero)
                {
                    NativeDbInterop.sdb_free_context(_nativeCtx);
                    _nativeCtx = IntPtr.Zero;
                }
            }
        }
    }

    /// <summary>
    /// Connection pool that manages native contexts with proper lifecycle.
    /// </summary>
    public sealed class ConnectionPool : IDisposable
    {
        private readonly ConcurrentBag<SecureDbConnection> _pool;
        private readonly AuditLogger _audit;
        private volatile bool _disposed;

        public ConnectionPool(string logPath, int initialSize = 4)
        {
            _audit = new AuditLogger(logPath);
            _pool = new ConcurrentBag<SecureDbConnection>();
            for (int i = 0; i < initialSize; i++)
                _pool.Add(new SecureDbConnection("default", _audit));
        }

        public SecureDbConnection Acquire()
        {
            if (_disposed) throw new ObjectDisposedException(nameof(ConnectionPool));
            if (_pool.TryTake(out var conn))
                return conn;
            return new SecureDbConnection("default", _audit);
        }

        public void Release(SecureDbConnection conn)
        {
            if (_disposed)
                conn?.Dispose();
            else
                _pool.Add(conn);
        }

        public void Dispose()
        {
            _disposed = true;
            while (_pool.TryTake(out var conn))
                conn.Dispose();
            _audit.Dispose();
        }
    }
